import{liveBoardData}from'./results-board-data.js';
import{occupationById}from'./occupation-data.js';
import{escapeHTML as h}from'./html.js';
export const boardRoutes=new Set(['plan','journey/professions','journey/explore']);
export const isResultsBoardRoute=r=>boardRoutes.has(r.split('?')[0]);
export function resultsBoardPage(s,{preview=false}={}){if(s&&!preview&&!s.guide?.lifestyleBuilder?.complete&&!s.guide?.lifestylePreset&&!s.guide?.salaryPicked)return `<section class="guide-input-panel"><h1>Picture your lifestyle first.</h1><a class="button" href="#/journey/lifestyle">Choose my lifestyle →</a><p><a href="#/retired-v1/plan">Retired v1 plan</a></p></section>`;return `<section class="results-board-host"><nav class="resource-return">${s?.guide?.primaryCareer?`<a href="#/journey/profession/${h(s.guide.primaryCareer)}">Chosen: ${h(occupationById(s.guide.primaryCareer)?.title||s.guide.primaryCareer)}</a>`:''}<a href="./results-board.html">View any model →</a><a href="#/retired-v1/results">Retired v1 results</a><a href="#/retired-v1/plan">Retired v1 plan</a></nav><iframe id="results-board-frame" title="Career results decision board" src="./results-board-frame.html?v=6e5476fd64a5" style="width:100%;height:2400px;border:0;display:block" loading="eager"></iframe></section>`;}
let stop;
export function connectResultsBoard(s,{persist=()=>{},navigate=r=>{location.hash='/'+r;},preview=false,route=''}={}){stop?.abort();stop=new AbortController();const frame=document.getElementById('results-board-frame');if(!frame)return;const data=liveBoardData(s),scope=new URLSearchParams(route.split('?')[1]||'').get('scope');if(scope&&scope!=='all'&&data.fields.some(f=>f.id===scope)){data.scopeTitle=data.fields.find(f=>f.id===scope).title;data.profiles[0].supported=data.profiles[0].supported.filter(o=>o.fields.includes(scope));data.profiles[0].candidates=data.profiles[0].candidates.filter(o=>o.fields.includes(scope));}const viewport=()=>frame.contentWindow.postMessage({type:'fieldguide-board-viewport',top:Math.max(0,-frame.getBoundingClientRect().top)+16,height:Math.max(250,window.innerHeight-48)},location.origin);window.addEventListener('scroll',viewport,{passive:true,signal:stop.signal});window.addEventListener('resize',viewport,{signal:stop.signal});const send=()=>frame.contentWindow.postMessage({type:'fieldguide-board-init',data,preview},location.origin);window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;const m=e.data;if(m?.type==='fieldguide-board-ready'){send();viewport();}if(m?.type==='fieldguide-board-dialog')viewport();if(m?.type==='fieldguide-board-height'&&Number.isFinite(m.height))frame.style.height=Math.max(800,Math.min(50000,m.height))+'px';if(m?.type==='fieldguide-board-navigate'&&/^(journey\/(profession\/[a-z0-9-]+|clarify\/[a-z0-9-]+\/0|interest\/(?:[0-5]?[0-9])|profile|lifestyle|explore)|plan)$/.test(m.route))navigate(m.route);if(m?.type==='fieldguide-board-save'&&data.profiles[0].supported.concat(data.profiles[0].candidates).some(o=>o.id===m.id)){s.careerLibrary??={};const ids=new Set(s.careerLibrary.saved||[]);m.saved?ids.add(m.id):ids.delete(m.id);s.careerLibrary.saved=[...ids];persist();}}, {signal:stop.signal});frame.addEventListener('load',send,{signal:stop.signal});}
